use std::fs
use std::process

fn fail() {
    println("error")
    process::exit(1)
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let lines: Vec<string> = text.lines().collect()
    if lines.len() < 1 {
        fail()
        return
    }
    let head: Vec<string> = lines[0].split_whitespace().map(|s| s.to_string()).collect()
    if head.len() != 2 {
        fail()
        return
    }
    let r: int = head[0].parse::<int>().unwrap_or(0)
    let c: int = head[1].parse::<int>().unwrap_or(0)
    if r < 1 || c < 1 {
        fail()
        return
    }
    let mut grid: Vec<Vec<int>> = []
    let mut i: int = 0
    while i < r {
        let idx = (i + 1) as usize
        if idx >= lines.len() {
            fail()
            return
        }
        let toks: Vec<string> = lines[idx].split_whitespace().map(|s| s.to_string()).collect()
        if toks.len() as int != c {
            fail()
            return
        }
        let mut row: Vec<int> = []
        for t in toks {
            let ok = t.parse::<int>().is_ok()
            if !ok {
                fail()
                return
            }
            row.push(t.parse::<int>().unwrap_or(0))
        }
        grid.push(row)
        i += 1
    }
    let mut top: int = 0
    let mut bot: int = r - 1
    let mut left: int = 0
    let mut right: int = c - 1
    let mut out: Vec<string> = []
    while top <= bot && left <= right {
        let mut j = left
        while j <= right {
            out.push("${grid[top as usize][j as usize]}")
            j += 1
        }
        top += 1
        j = top
        while j <= bot {
            out.push("${grid[j as usize][right as usize]}")
            j += 1
        }
        right -= 1
        if top <= bot {
            j = right
            while j >= left {
                out.push("${grid[bot as usize][j as usize]}")
                j -= 1
            }
            bot -= 1
        }
        if left <= right {
            j = bot
            while j >= top {
                out.push("${grid[j as usize][left as usize]}")
                j -= 1
            }
            left += 1
        }
    }
    println(out.join(" "))
}

